# -------------------------------------------------------------------------
# Project Manager (NEW)
# -------------------------------------------------------------------------

def get_project_manager(self) -> "ProjectManager":
    """Return a ProjectManager for this session."""
    from codx.junior.engine.project_manager import ProjectManager
    return ProjectManager(
        chat_manager=self.get_chat_manager(),
        settings=self.settings
    )

def get_project_dashboard(self) -> Dict[str, Any]:
    """Get complete project dashboard data."""
    return self.get_project_manager().get_dashboard_data()

def update_task_status(self, chat_id: str, status: str) -> Chat:
    """Update task status."""
    chat = self.get_chat_manager().find_by_id(chat_id=chat_id)
    if not chat:
        raise ValueError(f"Task {chat_id} not found")
    return self.get_chat_manager().update_task_metadata(
        chat=chat,
        updates={'status': status}
    )

def set_task_budget(self, chat_id: str, budget: float) -> Chat:
    """Set budget limit for a task."""
    chat = self.get_chat_manager().find_by_id(chat_id=chat_id)
    if not chat:
        raise ValueError(f"Task {chat_id} not found")
    return self.get_chat_manager().update_task_metadata(
        chat=chat,
        updates={'budget': budget}
    )

def update_task_cost(self, chat_id: str, additional_cost: float) -> Chat:
    """Increment task cost (called after AI execution)."""
    chat = self.get_chat_manager().find_by_id(chat_id=chat_id)
    if not chat:
        raise ValueError(f"Task {chat_id} not found")
    current_cost = chat.cost_spent or 0.0
    return self.get_chat_manager().update_task_metadata(
        chat=chat,
        updates={'cost_spent': current_cost + additional_cost}
    )
